from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def p(amt="2000.00"):
    return Payment("pay","inv",Decimal(amt),status="captured",created_at=T0,captured_at=T0)

# at threshold no approval
x=p(); outage_refund(x, Decimal("1000.00"), T0); print("1000 ok", x.refunded_amount)
# above threshold requires approval
try:
    outage_refund(p(), Decimal("1000.01"), T0)
except BillingError as e: print("above:", e.code)
# with approval
x=p(); outage_refund(x, Decimal("1000.01"), T0, approved_by="mgr"); print("approved", x.refunded_amount)
# full refund status
x=p("10.00"); outage_refund(x, Decimal("10.00"), T0); print("status", x.status)
# over captured
try:
    x=p("10.00"); outage_refund(x, Decimal("11.00"), T0, approved_by="mgr")
except BillingError as e: print("over:", e.code)
# non-captured
try:
    x=p(); x.status="authorized"; outage_refund(x, Decimal("1.00"), T0)
except BillingError as e: print("state:", e.code)
# non-positive
try:
    outage_refund(p(), Decimal("0"), T0)
except BillingError as e: print("nonpos:", e.code)
EOF"}

